#pragma once

#include <stdexcept>
#include <string>
#include <vector>

// A cone as returned by Task 1.
struct Cone {
    std::string side;
    double x;
    double y;
};

struct Point2 {
    double x;
    double y;
};

// Car pose from trajectory.csv: position in metres, yaw in radians.
struct Pose {
    double x;
    double y;
    double yaw;
};

// camera.json
struct CameraMount {
    double forward_offset_m;
    double height_m;
    double pitch_rad;
};

struct Camera {
    int image_width;
    int image_height;
    double fx;
    double fy;
    double cx;
    double cy;
    CameraMount mount;
};

struct Projection {
    int cone_index;
    double u;
    double v;
};

// Throw this from any task you are not attempting.
struct NotImplemented : std::logic_error {
    NotImplemented() : std::logic_error("not implemented") {}
};

// Task 1: read the cone file at `path`; one Cone per cone, in file order.
std::vector<Cone> parse_cones(const std::string& path);

// Task 2a: your proposed racing line as (x, y) points in metres,
// in the order the car drives them.
std::vector<Point2> plan_racing_line(const std::vector<Cone>& cones);

// Task 2b: (cone_index, u, v) for every cone visible to the camera when the car
// is at `pose`. cone_index is the cone's 0-based position in `cones`; (u, v) is
// the centre of the cone's base in pixels.
std::vector<Projection> project_cones(const std::vector<Cone>& cones,
                                      const Pose& pose,
                                      const Camera& camera);
